-- Minimal Supabase-compatible PostgreSQL fixture for CI only.
-- This is an isolated disposable database, never the user's Supabase project.

create schema if not exists extensions;
create extension if not exists vector with schema extensions;

do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then
    create role anon nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    create role authenticated nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then
    create role service_role nologin bypassrls;
  end if;
end;
$$;

create schema if not exists auth;
create schema if not exists storage;

create table auth.users (
  id uuid primary key,
  email text unique,
  created_at timestamptz not null default now()
);

create or replace function auth.uid()
returns uuid
language sql
stable
as $$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid;
$$;

grant usage on schema auth to anon, authenticated, service_role;
grant select on auth.users to authenticated, service_role;
grant usage on schema public to anon, authenticated, service_role;
grant usage on schema storage to anon, authenticated, service_role;
grant usage on schema extensions to anon, authenticated, service_role;

create table public.tenentes (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  created_at timestamptz not null default now()
);

create table public."case" (
  id uuid primary key default gen_random_uuid(),
  tenente_id uuid references public.tenentes(id),
  title text not null,
  description text,
  created_at timestamptz not null default now()
);

create table public."CASE" (
  id bigint generated by default as identity primary key,
  created_at timestamptz not null default now(),
  "Name" text
);
alter table public."CASE" enable row level security;

create table public.document (
  id uuid primary key default gen_random_uuid(),
  case_id uuid references public."case"(id),
  file_name text not null,
  file_path text,
  created_at timestamptz not null default now()
);

create table public.embedding (
  id uuid primary key default gen_random_uuid(),
  document_id uuid references public.document(id),
  content text not null,
  vector extensions.vector(3),
  created_at timestamptz not null default now()
);

create table storage.buckets (
  id text primary key,
  name text not null,
  public boolean not null default false,
  file_size_limit bigint,
  allowed_mime_types text[]
);

create table storage.objects (
  id uuid primary key default gen_random_uuid(),
  bucket_id text references storage.buckets(id),
  name text not null,
  owner_id text,
  metadata jsonb,
  created_at timestamptz not null default now(),
  unique (bucket_id, name)
);
alter table storage.objects enable row level security;

-- Reproduce broad default client grants so migrations must actively revoke them.
grant select, insert, update, delete on all tables in schema public to anon, authenticated;
grant select, insert, update, delete on storage.objects to anon, authenticated;
grant all on all tables in schema public to service_role;
grant all on all tables in schema storage to service_role;

